export const SUMMARY_LENGTHS = ["short", "medium", "detailed"] as const;
export const DIFFICULTIES = ["easy", "medium", "hard"] as const;

export type SummaryLength = (typeof SUMMARY_LENGTHS)[number];
export type Difficulty = (typeof DIFFICULTIES)[number];

export interface GenerationMeta {
  /** The Gemma model that produced the output. */
  model: string;
  /** Wall-clock generation time in milliseconds. */
  durationMs: number;
  /** Tokens generated by the model (as reported by the provider), if available. */
  outputTokens: number | null;
}

export interface QuizQuestion {
  id: string;
  question: string;
  options: string[];
  correctIndex: number;
  explanation: string;
}

export interface SummaryPayload {
  text: string;
  length: SummaryLength;
  meta: GenerationMeta;
}

export interface QuizPayload {
  questions: QuizQuestion[];
  difficulty: Difficulty;
  meta: GenerationMeta;
}

export interface CombinedPayload {
  summary: SummaryPayload;
  quiz: QuizPayload | null;
  quizError: string | null;
}
